	@Override
	protected void startUp()
	{
		executor = Executors.newFixedThreadPool(RENDER_THREADS, task ->
		{
			Thread thread = new Thread(task, "Advanced Map renderer");
			thread.setDaemon(true);
			return thread;
		});
		newViews();
		mapOpen = false;
		windowOpen = false;
		// what was read and drawn before the plugin was last stopped is gone with it: read and drawn again
		slayerShown = null;
		extrasRead = 0;
		farmingRead = 0;
		forgetWhatWasShown();
		// RuneLite starts a plugin on the Swing thread: the bundled tables (845 KB, a quarter second) are read off it;
		// everything reads them through fields that are empty until then, so a map opened at once shows them a moment late
		executor.execute(this::loadTables);
		reader = new CacheReader(GameCache.of(client));
		shortestPathRoute = new ShortestPathRoute();
		source = new ClientMapSource(reader);
		icons = new MapIcons();
		itemDiscs.clear();
		itemDiscsAsked.clear();
		icons.setItemPictures(this::itemDisc);
		labels = new MapLabels();
		labelsLoading = false;
		regionsListing = false;
		moveHiddenIcons();
		settings = readSettings();
		orbLeftClick = config.orbLeftClick();
		orbMenu = config.orbMenu();
		search.setSkipped(MapSearch.Scope.parse(config.searchSkipped()));
		progress = Progress.NONE;
		selection = null;
		plane = 0;
		images = new RegionImages(source, executor, icons);
		// RuneLite keeps the plugin object between a stop and a start: last run's failure and Sailing icons are not this
		// run's (a preparer step still finishing at the stop may have put some back after it forgot them)
		storeFailed = false;
		linksRead = false;
		YourPlaces.start();
		executor.execute(this::openStore);
		markerFiles = Executors.newSingleThreadExecutor(task ->
		{
			Thread thread = new Thread(task, "Advanced Map markers");
			thread.setDaemon(true);
			return thread;
		});
		markerFiles.execute(this::openMarkers);
		lastSeen = null;
		preparer = new MapPreparer(images, source, () -> true,
			() -> lastSeen != null ? lastSeen : LUMBRIDGE);
		preparer.start();
		messages = new MapMessages(this::openMap);
		painter = new MapPainter(images, messages, icons, labels, filters, sideList, search);
		painter.setMenu(menu);
		painter.setPins(pins, editor);
		painter.setExecutor(executor);
		// a new painter does not follow: neither does the map, until the locate button is pressed again
		following = false;
		painter.setMultiCombat(config.multiCombat());
		painter.setInfoOnHover(config.infoOnHover());
		painter.setHighestFirst(config.monsterOrder() == MonsterOrder.HIGHEST_FIRST);
		painter.setPlayerArrow(config.playerArrow());
		painter.setToPrepare(this::leftToPrepare);
		painter.setLinks(this::leadsTo);
		overlay = new MapOverlay(client, this, painter);
		gameBox = new GameBox(config.gameBounds(), config.gameMaximized());
		painter.setGameMaximized(gameBox.isMaximized());
		input = new MapInput(this, client::getCanvasWidth, client::getCanvasHeight);
		hotkey = new HotkeyListener(() -> config.toggleKey())
		{
			@Override
			public void hotkeyPressed()
			{
				toggleMap();
			}
		};
		// a tab in the sidebar: a button with no panel would go in the client's title bar instead
		panel = new AdvancedMapPanel(this, config.toggleKey().toString());
		button = NavigationButton.builder()
			.tooltip("Advanced Map")
			.icon(MapIcon.draw(16))
			.priority(7)
			.panel(panel)
			.build();

		overlayManager.add(overlay);
		mouseManager.registerMouseListener(input);
		mouseManager.registerMouseWheelListener(input);
		keyManager.registerKeyListener(input);
		keyManager.registerKeyListener(hotkey);
		if (config.sidebarButton())
		{
			clientToolbar.addNavigation(button);
		}
		welcomedThisRun = false;
		StateFile remembered;
		try
		{
			remembered = new StateFile(getPluginDirectory(), markerFiles);
		}
		catch (IOException e)
		{
			log.warn("Advanced Map cannot reach its data folder; what it remembers about this computer is kept for this"
				+ " run only", e);
			remembered = new StateFile(null);
		}
		state = remembered;
		String lastVersion = remembered.get(StateFile.LAST_VERSION);
		if (lastVersion.isEmpty() && !config.lastVersion().isEmpty())
		{
			// an earlier version kept it in the profile: moved here once, so this start counts as the update it is
			lastVersion = config.lastVersion();
			remembered.set(StateFile.LAST_VERSION, lastVersion);
			configManager.unsetConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.LAST_VERSION);
		}
		WhatsNew.Start start = WhatsNew.start(lastVersion);
		if (start.isUpdated())
		{
			// an update: the player has had the map before, so no Welcome, and their map counts as built (a game
			// update's few new regions never open the Welcome page); What's new opens with the map next time
			remembered.set(StateFile.WELCOMED, true);
			remembered.set(StateFile.MAP_BUILT, true);
			if (start.isNews())
			{
				remembered.set(StateFile.WHATS_NEW_FOR, WhatsNew.VERSION);
			}
		}
		if (!WhatsNew.VERSION.equals(lastVersion))
		{
			// the version is noted at once: a client closed before the map was next opened does not take its next start
			// for an update again (What's new waits in the file meanwhile)
			remembered.set(StateFile.LAST_VERSION, WhatsNew.VERSION);
		}
		mapBuilt = remembered.is(StateFile.MAP_BUILT);
		started = true;
	}

	/**
	 * Closes the side list, drops the selected marker and empties the search: RuneLite keeps the plugin object between
	 * a stop and a start, and these live in it, while the lines and marks they belonged to went with the stop.
	 */
	void forgetWhatWasShown()
	{
		sideList.close();
		pins.select(null);
		search.clear();
	}

	/** Reads every bundled table; the search's last, so that its index is built again with what the others read. */
	private void loadTables()
	{
		MiningSites.load();
		RareTrees.load();
		Transports.load();
		Shops.load();
		Spawns.load();
		MultiCombat.load();
		Farming.load();
		SlayerTask.load();
		MonsterInfo.load();
		DungeonPreview.load();
		search.load();
	}

	@Override
	protected void shutDown()
	{
		started = false;
		boolean wasOpen = mapOpen || windowOpen;
		mapOpen = false;
		windowOpen = false;
		// RuneLite stops a plugin on the Swing thread: the window goes at once, so no click on it can reach the plugin
		// after what follows is gone (a later start would otherwise find the map open from such a click)
		Runnable closeWindow = () ->
		{
			MapWindow open = window;
			window = null;
			if (open != null)
			{
				open.dispose();
			}
		};
		if (SwingUtilities.isEventDispatchThread())
		{
			closeWindow.run();
		}
		else
		{
			SwingUtilities.invokeLater(closeWindow);
		}
		giveKeysBack();
		if (wasOpen)
		{
			// other plugins following the map's state learn it closed
			clientThread.invokeLater(() -> postState(false));
		}
		// startUp may have stopped part way (it threw): undo only what it got to
		if (button != null)
		{
			clientToolbar.removeNavigation(button);
		}
		AdvancedMapPanel stoppedPanel = panel;
		if (stoppedPanel != null)
		{
			SwingUtilities.invokeLater(stoppedPanel::stop);
		}
		if (preparer != null)
		{
			preparer.stop();
		}
		if (hotkey != null)
		{
			keyManager.unregisterKeyListener(hotkey);
		}
		if (input != null)
		{
			keyManager.unregisterKeyListener(input);
			mouseManager.unregisterMouseWheelListener(input);
			mouseManager.unregisterMouseListener(input);
		}
		if (overlay != null)
		{
			overlayManager.remove(overlay);
		}
		if (reader != null)
		{
			reader.close();
		}
		if (executor != null)
		{
			executor.shutdownNow();
		}
		if (markerFiles != null)
		{
			// saves already asked for still finish
			markerFiles.shutdown();
		}
		markerFiles = null;
		if (messages != null)
		{
			messages.clear();
		}
		executor = null;
		reader = null;
		source = null;
		icons = null;
		labels = null;
		YourPlaces.forget();
		yourPlaces = Collections.emptyList();
		// RuneLite keeps the plugin object while it is off: let go of pictures and other plugins' pins
		itemDiscs.clear();
		itemDiscsAsked.clear();
		pins.setOthers(Collections.emptyList());
		images = null;
		preparer = null;
		panel = null;
		messages = null;
		painter = null;
		overlay = null;
		input = null;
		hotkey = null;
		button = null;
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		// one read of each field: the plugin may be stopping on the Swing thread while this frame runs
		CacheReader reads = reader;
		if (reads != null)
		{
			reads.service();
		}
		if (mapOpen || windowOpen)
		{
			WorldPoint before = player;
			player = Prifddinas.toSurface(currentPlayerLocation());
			if (!java.util.Objects.equals(before, player))
			{
				// the marker, and the view when following: a paint is due
				touched();
			}
			follow();
		}
		if (windowOpen)
		{
			windowScale = stretchedScale();
		}
		long now = System.currentTimeMillis();
		if ((mapOpen || windowOpen) && now - extrasRead >= EXTRAS_MILLIS)
		{
			extrasRead = now;
			readExtras(now);
		}
	}

	/** The house and boat pins last read: kept through a scene load, which drops none of them. */
	private volatile List<MapPins.Pin> yourPlaces = Collections.emptyList();

	/**
	 * The logged-in account's house and boat pins: read again while logged in, the last ones kept while a scene loads
	 * (a region's edge, a teleport, often while sailing), none while out of the game. Client thread.
	 */
	private List<MapPins.Pin> yourPlaces()
	{
		GameState state = client.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			try
			{
				// the names read once: the plugin may be stopping on the Swing thread meanwhile
				yourPlaces = YourPlaces.read(client, labelsNow(), progress.getCategoryNames());
			}
			catch (RuntimeException e)
			{
				// the game's own varbit table missing (seen on a fresh cache at the login screen, 2026-11-07): the last
				// pins kept, asked again a second later, never an error out of the frame
				log.debug("could not read the house and boats", e);
			}
		}
		else if (state != GameState.LOADING && state != GameState.HOPPING)
		{
			// out of the game; a scene load or a world hop keeps the account and its pins
			yourPlaces = Collections.emptyList();
		}
		return yourPlaces;
	}

	/**
	 * Reads what other plugins and RuneLite keep that the map shows: other plugins' world map markers, the farming
	 * patches Time Tracking saved (every {@link #FARMING_MILLIS}), the Slayer task. Client thread.
	 */
	private void readExtras(long now)
	{
		List<MapPins.Pin> others = new ArrayList<>();
		if (config.pluginMarkers())
		{
			// RuneLite lists the markers only to plugins of its own; a check that keeps every marker reads them all
			worldMapPointManager.removeIf(point ->
			{
				MapPins.Pin pin = pinOf(point);
				if (pin != null)
				{
					others.add(pin);
				}
				return false;
			});
		}
		if (config.yourPlaces())
		{
			others.addAll(yourPlaces());
		}
		pins.setOthers(others);
		String account = account();
		pins.setFilter(config.shareMarkers(), account);
		if (sideList.owner() == MARKERS_LIST && sideList.isOpen() && !java.util.Objects.equals(account, markersFor))
		{
			if (account == null && !config.shareMarkers())
			{
				// logged out with the window open and markers kept apart: no account's markers are "yours" now
				sideList.close();
			}
			else
			{
				// another account logged in with the window open: its markers, not the last one's
				showMarkers();
			}
		}
		MapPainter drawing = painter;
		if (drawing != null && now - farmingRead >= FARMING_MILLIS)
		{
			farmingRead = now;
			drawing.setFarming(config.farmingStatus() ? readFarming(now / 1000) : null);
		}
		showSlayerTask();
		// other plugins' markers, the farming dots, the Slayer marks: read again, so a paint is due
		touched();
	}

	/**
	 * Another plugin's world map marker as a pin; null for RuneLite's World Map plugin's (Advanced Map has those icons
	 * itself) and for a marker with no picture.
	 */
	static MapPins.Pin pinOf(WorldMapPoint point)
	{
		if (point.getImage() == null || point.getWorldPoint() == null
			|| point.getClass().getName().startsWith(CORE_WORLD_MAP))
		{
			return null;
		}
		String name = point.getName() != null ? point.getName() : point.getTooltip() != null ? point.getTooltip() : "";
		return new MapPins.Pin(point.getWorldPoint(), point.getImage(), null, name, point.getTooltip(),
			point.isJumpOnClick() ? point.getTarget() : null, point.isSnapToEdge());
	}

	/** Each farming site's patches as Time Tracking saved them for this account. */
	private Map<Farming.Site, List<Farming.Reading>> readFarming(long now)
	{
		Map<Farming.Site, List<Farming.Reading>> out = new java.util.HashMap<>();
		java.util.function.Function<String, String> saved = key ->
			configManager.getRSProfileConfiguration(Farming.GROUP, key);
		for (Farming.Site site : Farming.sites())
		{
			out.put(site, Farming.readings(site, saved, now));
		}
		return out;
	}

	/**
	 * Names the Slayer task RuneLite's Slayer plugin has saved at the top of the Filters list, and marks its spawns
	 * while "Your Slayer task" is ticked there.
	 */
	private void showSlayerTask()
	{
		MapMessages layers = messages;
		if (layers == null)
		{
			return;
		}
		String task = configManager.getRSProfileConfiguration(SlayerTask.GROUP, SlayerTask.TASK_NAME);
		String amount = task == null ? null : configManager.getRSProfileConfiguration(SlayerTask.GROUP,
			SlayerTask.AMOUNT);
		boolean assigned = task != null && !task.isEmpty() && amount != null && !"0".equals(amount);
		filters.setSlayerTask(assigned ? task + " (" + amount + " left)" : null);
		boolean active = assigned && config.slayerShown();
		// the place names narrow a Konar task to its area: drawn again once they have loaded
		String key = active ? task + ":" + amount + ":" + !labelsNow().isEmpty() : null;
		if (java.util.Objects.equals(key, slayerShown))
		{
			return;
		}
		slayerShown = key;
		if (!active)
		{
			layers.remove(SlayerTask.LAYER);
			return;
		}
		List<WorldPoint> spawns = SlayerTask.spawns(task);
		if (spawns.isEmpty())
		{
			layers.remove(SlayerTask.LAYER);
			return;
		}
		String location = configManager.getRSProfileConfiguration(SlayerTask.GROUP, SlayerTask.LOCATION);
		List<SearchSpots.Area> areas = SearchSpots.areas(spawns, player != null ? player : LUMBRIDGE, labelsNow());
		if (location != null && !location.isEmpty())
		{
			// a Konar task names its place: only areas named for it, when any are
			List<SearchSpots.Area> there = new ArrayList<>(areas);
			there.removeIf(area -> !area.getName().toLowerCase(java.util.Locale.ROOT)
				.contains(location.toLowerCase(java.util.Locale.ROOT)));
			if (!there.isEmpty())
			{
				areas = there;
			}
		}
		layers.put(SlayerTask.layer(areas, spawns, task + " (" + amount + " left)"));
	}

	/** The world map orb, in each of the game's minimap layouts. */
	private static final Set<Integer> ORB = new HashSet<>(Arrays.asList(
		InterfaceID.Orbs.ORB_WORLDMAP, InterfaceID.Orbs.WORLDMAP,
		InterfaceID.OrbsNomap.ORB_WORLDMAP, InterfaceID.OrbsNomap.WORLDMAP,
		InterfaceID.OrbsOsm.ORB_WORLDMAP, InterfaceID.OrbsOsm.WORLDMAP,
		InterfaceID.OrbsOsmNomap.ORB_WORLDMAP, InterfaceID.OrbsOsmNomap.WORLDMAP));
	private static final String ORB_OPTION = "Open";
	private static final String ORB_TARGET = ColorUtil.wrapWithColorTag("Advanced Map", JagexColors.MENU_TARGET);

	/**
	 * Adds "Open Advanced Map" to the world map orb's menu, once the game has sorted it: second, right under the
	 * game's left-click option (the menu's top entry is always the left click), or at the top when it is to be the
	 * left click. The game's own entries stay as they are. It only opens
	 * this plugin's map; nothing is sent to the game. After the other plugins: one that also puts its own entry on top
	 * of the orb's menu would otherwise take the left click from it while this one's setting asks for it; theirs stays
	 * in the menu, right under it.
	 */
	@Subscribe(priority = -1)
	public void onPostMenuSort(PostMenuSort event)
	{
		boolean left = orbLeftClick;
		if (reader == null || !left && !orbMenu || client.isMenuOpen())
		{
			return;
		}
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		boolean orb = false;
		for (int i = 0; i < entries.length; i++)
		{
			if (ORB_TARGET.equals(entries[i].getTarget()))
			{
				if (left && i != entries.length - 1)
				{
					menu.setMenuEntries(toTop(entries, i));
				}
				return;
			}
			orb |= ORB.contains(entries[i].getParam1());
		}
		if (!orb)
		{
			return;
		}
		menu.createMenuEntry(left ? -1 : -2)
			.setOption(ORB_OPTION)
			.setTarget(ORB_TARGET)
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> openMap(null, null));
	}

	/** A menu with one entry moved to the top (the last one, which a left click takes); the others keep their order. */
	static <T> T[] toTop(T[] entries, int index)
	{
		T[] moved = Arrays.copyOf(entries, entries.length);
		System.arraycopy(entries, index + 1, moved, index, entries.length - index - 1);
		moved[entries.length - 1] = entries[index];
		return moved;
	}

