	/**
	 * Whether a routing plugin is installed and running, found by name in RuneLite's own plugin list (read only;
	 * nothing of the other plugin is touched). Without it "Route here" would send a message nobody answers.
	 */
	private boolean routingRunning(RoutingPlugin routing)
	{
		if (routing == null || routing.getPluginName() == null)
		{
			return false;
		}
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin != null && routing.getPluginName().equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	/**
	 * Leaving the game (logout, a disconnect, a world hop) closes the map over the game view: RuneLite stops drawing
	 * overlays there, and an invisible map would still take every click on the login screen. The window stays.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (mapOpen && (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST))
		{
			closeMap();
			// nothing is drawn until the next login, so the overlay cannot let its picture go itself
			MapOverlay drawn = overlay;
			if (drawn != null)
			{
				drawn.forget();
			}
		}
		if ((mapOpen || windowOpen) && state == GameState.LOGGED_IN)
		{
			// a load just ended, or a login or hop: the account's levels and quests are read on the next tick, when the
			// game has them (after a login they arrive a tick after this event), not at the refresh up to 3 s later
			progressDue = true;
		}
		if (windowOpen && state == GameState.LOGIN_SCREEN)
		{
			// the window stays open, and no game tick comes on the login screen to read the account again: read now, so
			// it stops showing the last account's quests, levels and locks (client thread). A hop keeps the account, so
			// it keeps them through the hop as through a scene load, read again on the tick after it
			readProgress();
		}
		MapInput keys = input;
		if (keys != null && state == GameState.LOGIN_SCREEN)
		{
			// the login screen gets no key events through this listener, the releases of keys held into it included;
			// the keys' owner is the Swing thread's
			SwingUtilities.invokeLater(keys::forgetKeys);
		}
	}

