	/**
	 * A left press on the search bar takes the keys (and closes the Filters list), its x empties it, a result is
	 * chosen; a press anywhere else leaves the bar. True when the press was on the bar or its results.
	 */
	private boolean pressSearch(int x, int y, int width, int height, boolean window)
	{
		MapSearch.Layout layout = search.layout(MapPainter.buttons(width, height, window), width);
		MapSearch.Hit hit = search.hitAt(x, y, layout);
		switch (hit.getPart())
		{
			case BOX:
				search.setFocused(true);
				search.setScopesOpen(false);
				filters.setOpen(false);
				selection = null;
				return true;
			case SCOPES:
				// the "Search in" list; the bar keeps the keys, so typing shows the results again
				search.setScopesOpen(!search.isScopesOpen());
				search.setFocused(true);
				filters.setOpen(false);
				selection = null;
				return true;
			case SCOPE:
				setSearchScope(hit.getIndex());
				return true;
			case CLEAR:
				search.clear();
				search.setFocused(true);
				return true;
			case RESULT:
				choose(search.results().get(hit.getIndex()));
				return true;
			default:
				search.setFocused(false);
				return false;
		}
	}

	/**
	 * A row of the "Search in" list: 0 "Search everything", else a kind of result turned off or on; saved, and the
	 * query searched again.
	 */
	private void setSearchScope(int row)
	{
		java.util.Set<MapSearch.Scope> off = java.util.EnumSet.noneOf(MapSearch.Scope.class);
		if (row > 0)
		{
			off.addAll(search.skipped());
			MapSearch.Scope scope = MapSearch.Scope.values()[row - 1];
			if (!off.remove(scope))
			{
				off.add(scope);
			}
		}
		search.setSkipped(off);
		search.searchAgain(searchIndex(), here());
		configManager.setConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.SEARCH_SKIPPED,
			MapSearch.Scope.save(off));
	}

	/** Everything the search bar finds, built again once the place names are read. */
	private List<MapSearch.Entry> searchIndex()
	{
		List<MapSearch.Entry> all = search.index(labelsNow(), extraEntries());
		boolean shops = config.searchShops();
		if (shops && search.skipped().isEmpty())
		{
			return all;
		}
		// shops only through what they sell (an item's sellers) and their icons, unless the setting says otherwise;
		// nothing of what the "Search in" list leaves out
		List<MapSearch.Entry> out = new ArrayList<>(all.size());
		for (MapSearch.Entry entry : all)
		{
			if ((shops || entry.getKind() != MapSearch.Kind.SHOP) && search.looksIn(entry))
			{
				out.add(entry);
			}
		}
		return out;
	}

	/** Where search measures "nearest" from: the player, or the middle of the map while logged out. */
	private WorldPoint here()
	{
		return player != null ? player : center();
	}

	/**
	 * The search entries that change while the plugin runs: the player's markers, and each kind of map icon found so
	 * far ("Bank", "Anvil": every one of them, to list the nearest). Built again when either changes.
	 */
	private List<MapSearch.Entry> extraEntries()
	{
		MapIcons known = icons;
		List<MapPins.Marker> markers = pins.shown();
		List<MapSpot> spots = known == null ? Collections.emptyList() : known.allSpots();
		Map<String, WorldPoint> maps = gameMaps;
		Object key = Arrays.asList(markers, spots.size(), progress, maps);
		if (key.equals(extraKey))
		{
			return extraEntries;
		}
		List<MapSearch.Entry> out = new ArrayList<>();
		for (MapPins.Marker marker : markers)
		{
			out.add(new MapSearch.Entry(MapSearch.Kind.MARKER, marker.getName().isEmpty() ? "Marker"
				: marker.getName(), MapSearch.Kind.MARKER.label, Collections.singletonList(marker.getPoint()),
				Collections.emptyList(), null));
		}
		// the game's own maps by name: Zanaris has no place name of its own on any map; a name that is one already is
		// found that way
		java.util.Set<String> placeNames = new java.util.HashSet<>();
		for (MapLabels.Label label : labelsNow())
		{
			placeNames.add(MapSearch.normalize(String.join(" ", label.getLines())));
		}
		maps.forEach((name, at) ->
		{
			if (!placeNames.contains(MapSearch.normalize(name)))
			{
				out.add(new MapSearch.Entry(MapSearch.Kind.PLACE, name, "Place",
					Collections.singletonList(at), Collections.emptyList(), null));
			}
		});
		Map<Integer, List<WorldPoint>> byCategory = new java.util.TreeMap<>();
		for (MapSpot spot : spots)
		{
			if (spot.getTeleport() == null && spot.getCategory() >= 0 && spot.getCategory() != IconGroup.MAP_LINK)
			{
				byCategory.computeIfAbsent(spot.getCategory(), k -> new ArrayList<>())
					.add(new WorldPoint(spot.getX(), spot.getY(), spot.getPlane()));
			}
		}
		byCategory.forEach((category, points) ->
		{
			String name = progress.categoryName(category);
			if (name != null)
			{
				out.add(new MapSearch.Entry(MapSearch.Kind.ICON, name, points.size() == 1 ? "Map icon"
					: points.size() + " on the map", points, Collections.emptyList(), null));
			}
		});
		extraEntries = Collections.unmodifiableList(out);
		extraKey = key;
		return extraEntries;
	}

	/**
	 * Shows a search result: moves the map to the nearest of its places (to the player, or the map's middle) and, for
	 * a shop, lists its stock; for an item, its sellers, nearest first; for a monster or NPC, marks every spawn and
	 * lists them by area, nearest first.
	 */
	private void choose(MapSearch.Entry entry)
	{
		if (entry == null || entry.getPoints().isEmpty())
		{
			return;
		}
		search.setFocused(false);
		selection = null;
		showTransport(null);
		WorldPoint from = player != null ? player : center();
		WorldPoint nearest = nearest(entry.getPoints(), from);
		switch (entry.getKind())
		{
			case SHOP:
				showShop(entry.getShops().get(0));
				break;
			case ITEM:
				sideList.open(entry.getName(), sellerRows(entry, from), entry);
				break;
			case FAIRY_RING:
			{
				List<Transports.Destination> to = Transports.from(nearest.getX(), nearest.getY(), nearest.getPlane(),
					"Fairy ring");
				if (!to.isEmpty())
				{
					messages.put(Transports.layer(nearest, to));
					sideList.open(entry.getName(), transportRows(nearest, to), entry);
				}
				break;
			}
			case ICON:
				MapIcons current = icons;
				sideList.open("Nearest: " + entry.getName(), nearestRows(entry.getPoints(), from, entry.getName(),
					current == null ? Collections.emptyList() : current.allSpots(), progress, labelsNow()), entry);
				break;
			case MONSTER:
			case NPC:
			case GROUND_ITEM:
			case FISHING:
			case HUNTER:
				List<SearchSpots.Area> areas = SearchSpots.areas(entry.getPoints(), from, labelsNow(),
					entry.getCreature() != null ? entry.getCreature().getFloors() : Collections.emptyMap());
				nearest = areas.get(0).getPoint();
				messages.put(SearchSpots.layer(SEARCH_LAYER, entry.getPoints()));
				List<SideList.Row> rows = new ArrayList<>();
				MonsterInfo.Monster monster = entry.getKind() == MapSearch.Kind.MONSTER ? MonsterInfo.of(entry.getName())
					: null;
				if (monster != null)
				{
					// what the monster is like first, then where it is
					rows.addAll(MonsterInfo.rows(monster));
					rows.add(SideList.Row.heading("Locations (nearest first)"));
				}
				rows.addAll(SearchSpots.rows(areas, entry.getKind() == MapSearch.Kind.FISHING
					|| entry.getKind() == MapSearch.Kind.GROUND_ITEM ? "spot"
					: entry.getKind() == MapSearch.Kind.HUNTER ? "area" : "spawn"));
				sideList.open(entry.getName() + (entry.getKind() == MapSearch.Kind.MONSTER
					? " (" + entry.getNote().toLowerCase(java.util.Locale.ROOT) + ")" : ""), rows, entry);
				break;
			default:
				if (entry.getPoints().size() > 1)
				{
					messages.put(SearchSpots.layer(SEARCH_LAYER, entry.getPoints()));
				}
				break;
		}
		goTo(nearest, SEARCH_ZOOM);
	}

	/** Every place of a kind of map icon, nearest first: named by the game's nearest place name, with how far. */
	static List<SideList.Row> nearestRows(List<WorldPoint> points, WorldPoint from, String kind, List<MapSpot> all,
		Progress progress, List<MapLabels.Label> labels)
	{
		List<WorldPoint> sorted = new ArrayList<>(points);
		sorted.sort(java.util.Comparator.comparingInt(point -> SearchSpots.distance(point, from)));
		// each called as its box calls it (a minigame, a shortcut, a named icon), else by the nearest place's name
		// (Guardians of the Rift read "Queen's Chamber", the Tears of Guthix "Giant frogs"; owner, 2026-11-07)
		Map<WorldPoint, MapSpot> spots = new java.util.HashMap<>();
		for (MapSpot spot : all)
		{
			if (kind.equals(progress.categoryName(spot.getCategory())))
			{
				spots.put(new WorldPoint(spot.getX(), spot.getY(), spot.getPlane()), spot);
			}
		}
		List<SideList.Row> rows = new ArrayList<>();
		for (WorldPoint point : sorted)
		{
			int tiles = SearchSpots.distance(point, from);
			MapSpot spot = spots.get(point);
			String own = spot == null ? null : MapIcons.name(spot, progress);
			rows.add(new SideList.Row(own != null && !own.equals(kind) ? own : SearchSpots.name(point, labels),
				tiles >= 1000 ? "far" : tiles + " tiles", null, null, point, null));
		}
		return rows;
	}

	/** An item's sellers, nearest first: the shop, the price there; a click opens the shop's stock. */
	private static List<SideList.Row> sellerRows(MapSearch.Entry item, WorldPoint from)
	{
		List<Shops.Shop> shops = new ArrayList<>(item.getShops());
		shops.sort(java.util.Comparator.comparingInt(shop -> SearchSpots.distance(shop.getPoint(), from)));
		List<SideList.Row> rows = new ArrayList<>();
		for (Shops.Shop shop : shops)
		{
			String price = "";
			for (Shops.Item sold : shop.getItems())
			{
				if (sold.getName().equals(item.getName()))
				{
					price = sold.priceText();
					break;
				}
			}
			rows.add(new SideList.Row(shop.getName(), price, null, null, shop.getPoint(), shop));
		}
		return rows;
	}

	private static WorldPoint nearest(List<WorldPoint> points, WorldPoint from)
	{
		WorldPoint best = points.get(0);
		for (WorldPoint point : points)
		{
			if (SearchSpots.distance(point, from) < SearchSpots.distance(best, from))
			{
				best = point;
			}
		}
		return best;
	}

	/** A new GitHub issue on the map, its title and the spot filled in; the player writes what is wrong. */
	static String reportUrl(String spotText)
	{
		try
		{
			String enc = java.nio.charset.StandardCharsets.UTF_8.name();
			return AdvancedMapPanel.GITHUB_URL + "/issues/new?title=" + java.net.URLEncoder.encode("Map: " + spotText,
				enc) + "&body=" + java.net.URLEncoder.encode("Where: " + spotText + "\nAdvanced Map " + WhatsNew.VERSION
				+ "\n\nWhat is wrong or missing:\n\n\nA picture of the map is on your clipboard: paste it here"
				+ " (Ctrl+V).\n", enc);
		}
		catch (java.io.UnsupportedEncodingException e)
		{
			throw new IllegalStateException(e);
		}
	}

	/** The side list of the menu's "Your markers", and of its "Hidden icons"; a hidden icon's rows too. */
	static final Object MARKERS_LIST = new Object();
	static final Object HIDDEN_LIST = new Object();
	/** How far in a click on a hidden icon's row zooms, from further out: where icons are drawn, with room around. */
	private static final double HIDDEN_ZOOM = 3;
	/** The account "Your markers" was listed for. */
	private volatile String markersFor;

	/**
	 * Closes "Your markers" and "Hidden icons" as the map closes: they were made for the account, the markers and the
	 * settings of then, which a logout, another account or another client may change before the map opens again.
	 */
	void closeMenuLists()
	{
		Object owner = sideList.owner();
		if (owner == MARKERS_LIST || owner == HIDDEN_LIST)
		{
			sideList.close();
		}
	}

	/** A row that only informs: no place, nothing to open. */
	private static SideList.Row note(String text)
	{
		return new SideList.Row(text, null, null, null, null, null);
	}

	/** How far a place is, as the lists say it. */
	private static String tilesAway(WorldPoint point, WorldPoint from)
	{
		int tiles = SearchSpots.distance(point, from);
		return tiles >= 1000 ? "far" : tiles + " tiles";
	}

	/** The menu's "Your markers": every marker that shows, nearest first, where it is; a click goes there. */
	void showMarkers()
	{
		WorldPoint from = player != null ? player : center();
		List<MapPins.Marker> markers = pins.shown();
		markersFor = pins.filterAccount();
		sideList.open("Your markers (" + markers.size() + "), nearest first", markerRows(markers, from, labelsNow()),
			MARKERS_LIST);
	}

	/** The rows of "Your markers": each marker, nearest {@code from} first, how far and where; none, how to add one. */
	static List<SideList.Row> markerRows(List<MapPins.Marker> shown, WorldPoint from, List<MapLabels.Label> labels)
	{
		List<MapPins.Marker> markers = new ArrayList<>(shown);
		markers.sort(java.util.Comparator.comparingInt(marker -> SearchSpots.distance(marker.getPoint(), from)));
		List<SideList.Row> rows = new ArrayList<>();
		if (markers.isEmpty())
		{
			rows.add(note("None yet. Right-click anywhere on the map and choose \"Add marker here\"."));
		}
		for (MapPins.Marker marker : markers)
		{
			rows.add(new SideList.Row(marker.getName().isEmpty() ? "Marker" : marker.getName(),
				tilesAway(marker.getPoint(), from), SearchSpots.name(marker.getPoint(), labels), null,
				marker.getPoint(), null));
		}
		return rows;
	}

	/**
	 * The menu's "Hidden icons": every icon hidden with a right-click, nearest first; a click goes there and shows the
	 * hidden icons, faded, so it can be unhidden. Icons not found yet this run (found as the map shows or scans their
	 * places) are only counted.
	 */
	void showHiddenIcons()
	{
		Set<String> hidden = settings.getHidden();
		WorldPoint from = player != null ? player : center();
		List<MapSpot> candidates = new ArrayList<>(icons.allSpots());
		candidates.addAll(MapIcons.teleports());
		sideList.open("Hidden icons (" + hidden.size() + "), nearest first", hiddenRows(hidden, candidates, from,
			labelsNow(), progress), HIDDEN_LIST);
	}

	/**
	 * The rows of "Hidden icons": a line on what a click does, then each hidden icon found among {@code candidates},
	 * nearest {@code from} first, and how many hidden icons are not found yet (their places' icons not loaded).
	 */
	static List<SideList.Row> hiddenRows(Set<String> hidden, List<MapSpot> candidates, WorldPoint from,
		List<MapLabels.Label> labels, Progress progress)
	{
		java.util.Map<String, MapSpot> found = new java.util.LinkedHashMap<>();
		for (MapSpot spot : candidates)
		{
			if (hidden.contains(spot.getKey()))
			{
				found.putIfAbsent(spot.getKey(), spot);
			}
		}
		List<MapSpot> spots = new ArrayList<>(found.values());
		spots.sort(java.util.Comparator.comparingInt(spot -> SearchSpots.distance(point(spot), from)));
		List<SideList.Row> rows = new ArrayList<>();
		rows.add(note(hidden.isEmpty() ? "None. Right-click an icon and choose Hide to hide it."
			: "Click one to go there: it shows faded (unless Icons is off or its kind is unticked in Filters)."
				+ " Right-click it and choose Unhide."));
		for (MapSpot spot : spots)
		{
			rows.add(new SideList.Row(MapIcons.name(spot, progress), tilesAway(point(spot), from),
				SearchSpots.name(point(spot), labels), null, point(spot), HIDDEN_LIST));
		}
		int notFound = hidden.size() - spots.size();
		if (notFound > 0)
		{
			rows.add(note(notFound + " more not found yet: they are listed as the map finds their places' icons."));
		}
		return rows;
	}

	private static WorldPoint point(MapSpot spot)
	{
		return new WorldPoint(spot.getX(), spot.getY(), spot.getPlane());
	}

	/** The tile at the middle of the map as it is shown now. */
	private WorldPoint center()
	{
		MapViewport.View view = viewport().view(2, 2);
		return new WorldPoint((int) view.worldX(1), (int) view.worldY(1), plane);
	}

	private List<MapLabels.Label> labelsNow()
	{
		MapLabels names = labels;
		return names == null ? Collections.emptyList() : names.all();
	}

	/** True while a search box has the keys: the search bar's, or the open Filters list's. */
	boolean typing()
	{
		return editor.isOpen() || search.isFocused() || filtersOpen();
	}

	/** A key typed while {@link #typing}: into the search bar, else the Filters list's search box. */
	void type(char c)
	{
		Caret.typed();
		if (Character.isISOControl(c))
		{
			return;
		}
		if (editor.isOpen())
		{
			editor.type(c);
		}
		else if (search.isFocused())
		{
			search.type(c, searchIndex(), here());
		}
		else
		{
			typeFilters(c);
		}
	}

	/** A key pressed while {@link #typing}: Backspace, and in the search bar Up, Down and Enter to pick a result. */
	void typingKey(int keyCode)
	{
		Caret.typed();
		if (editor.isOpen())
		{
			if (keyCode == KeyEvent.VK_BACK_SPACE)
			{
				editor.backspace();
			}
			else if (keyCode == KeyEvent.VK_ENTER)
			{
				finishMarker();
			}
			return;
		}
		if (!search.isFocused())
		{
			if (keyCode == KeyEvent.VK_BACK_SPACE)
			{
				backspaceFilters();
			}
			return;
		}
		switch (keyCode)
		{
			case KeyEvent.VK_BACK_SPACE:
				search.backspace(searchIndex(), here());
				break;
			case KeyEvent.VK_UP:
				search.move(-1);
				break;
			case KeyEvent.VK_DOWN:
				search.move(1);
				break;
			case KeyEvent.VK_ENTER:
				choose(search.chosen());
				break;
			default:
				break;
		}
	}

	/**
	 * A left press while a transport's places are listed: a place moves the map there, the close box closes the list
	 * and the lines. True when the press was on the list.
	 */
	private boolean pressSideList(int x, int y, int width, int height, boolean window)
	{
		if (!sideList.isOpen())
		{
			return false;
		}
		SideList.Layout layout = sideList.layout(MapPainter.buttons(width, height, window));
		SideList.Hit hit = sideList.hitAt(x, y, layout);
		if (hit.getIndex() == SideList.Hit.OUTSIDE)
		{
			return false;
		}
		if (hit.getIndex() == SideList.Hit.CLOSE)
		{
			selection = null;
			showTransport(null);
		}
		else if (hit.getIndex() >= 0)
		{
			SideList.Row row = hit.getRow();
			if (row.getPoint() != null)
			{
				selection = null;
				// a hidden icon is to be unhidden: close enough in for icons to be drawn, as part of the jump
				goTo(row.getPoint(), row.getTarget() == HIDDEN_LIST
					&& viewports.get(area).view(1, 1).zoom < MapIcons.ICON_ZOOM ? HIDDEN_ZOOM : 0);
			}
			if (row.getTarget() instanceof Shops.Shop)
			{
				showShop((Shops.Shop) row.getTarget());
			}

			else if (row.getTarget() instanceof MonsterInfo.WikiPage)
			{
				LinkBrowser.browse(((MonsterInfo.WikiPage) row.getTarget()).getUrl());
			}
			else if (row.getTarget() == HIDDEN_LIST)
			{
				// to unhide it, it must show: hidden icons shown (and close enough in, above)
				if (!settings.isShowHidden())
				{
					setSwitch(AdvancedMapConfig.SHOW_HIDDEN, true);
				}
			}
		}
		return true;
	}

	private boolean pressFilters(int x, int y, int width, int height, boolean window)
	{
		MapFilters list = filters;
		if (list == null || !list.isOpen())
		{
			return false;
		}
		java.awt.Rectangle button = MapPainter.buttons(width, height, window).get(MapPainter.Button.FILTERS);
		List<MapFilters.Entry> entries = list.entries(progress);
		MapFilters.Hit hit = list.hitAt(x, y, MapFilters.layout(button, height), entries);
		switch (hit.getPart())
		{
			case OUTSIDE:
				if (!button.contains(x, y))
				{
					list.setOpen(false);
				}
				return false;
			case ALL_ON:
				for (IconGroup group : IconGroup.values())
				{
					configManager.setConfiguration(AdvancedMapConfig.GROUP, group.key, true);
				}
				configManager.setConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.HIDDEN_TYPES, "");
				break;
			case ALL_OFF:
				for (IconGroup group : IconGroup.values())
				{
					configManager.setConfiguration(AdvancedMapConfig.GROUP, group.key, false);
				}
				break;
			case MULTI_COMBAT:
				// the painter follows the setting's change, as it did from the settings panel
				configManager.setConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.MULTI_COMBAT,
					!config.multiCombat());
				break;
			case SHOW_HIDDEN:
				configManager.setConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.SHOW_HIDDEN,
					!settings.isShowHidden());
				break;
			case SLAYER:
				setSwitch(AdvancedMapConfig.SLAYER_SHOWN, !settings.isSlayerShown());
				clientThread.invokeLater(this::showSlayerTask);
				break;
			case ENTRY:
				toggle(hit.getEntry());
				break;
			default:
				break;
		}
		settings = readSettings();
		return true;
	}

	/**
	 * Turns a group or kind on or off. A group turned on shows all its kinds again; a kind turned on while its group is
	 * off turns the group on with only that kind.
	 */
	private void toggle(MapFilters.Entry entry)
	{
		IconGroup group = entry.getGroup();
		java.util.Set<String> hidden = new java.util.LinkedHashSet<>(settings.getHiddenTypes());
		if (entry.isGroup())
		{
			boolean on = !settings.shows(group);
			if (on)
			{
				hidden.removeIf(key -> MapSettings.groupOf(key) == group);
			}
			configManager.setConfiguration(AdvancedMapConfig.GROUP, group.key, on);
		}
		else if (!settings.shows(group))
		{
			hidden.addAll(filters.keysOf(group));
			hidden.remove(entry.getKey());
			configManager.setConfiguration(AdvancedMapConfig.GROUP, group.key, true);
		}
		else if (!hidden.remove(entry.getKey()))
		{
			hidden.add(entry.getKey());
		}
		configManager.setConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.HIDDEN_TYPES,
			String.join(MapSettings.SEPARATOR, hidden));
	}

	/** The mouse wheel over the Filters list or a transport's places scrolls it. True when it did. */
	boolean wheelPanels(int x, int y, double notches, int width, int height, boolean window)
	{
		if (menu.isOpen())
		{
			MapMenu.Layout open = menu.layout(MapPainter.buttons(width, height, window), width, height);
			if (open.getContent() != null && open.getContent().contains(x, y))
			{
				menu.scroll(notches, open);
				return true;
			}
			if (open.getMenu().contains(x, y))
			{
				return true;
			}
		}
		if (search.isScopesOpen()
			&& search.layout(MapPainter.buttons(width, height, window), width).getResults().contains(x, y))
		{
			// the "Search in" list does not scroll, and the map under it does not zoom
			return true;
		}
		if (!search.results().isEmpty())
		{
			// the search's results scroll under the mouse
			MapSearch.Layout found = search.layout(MapPainter.buttons(width, height, window), width);
			if (found.getResults().contains(x, y))
			{
				search.scroll(notches);
				return true;
			}
		}
		if (sideList.isOpen() && !editor.isOpen())
		{
			SideList.Layout places = sideList.layout(MapPainter.buttons(width, height, window));
			if (places.getPanel().contains(x, y))
			{
				sideList.scroll(notches, places);
				return true;
			}
		}
		MapFilters list = filters;
		if (list == null || !list.isOpen())
		{
			return false;
		}
		java.awt.Rectangle button = MapPainter.buttons(width, height, window).get(MapPainter.Button.FILTERS);
		MapFilters.Layout layout = MapFilters.layout(button, height);
		if (!layout.getPanel().contains(x, y))
		{
			return false;
		}
		list.scroll(notches, layout, list.entries(progress).size());
		return true;
	}

	/** A key typed while the Filters list is open: into its search box. */
	private void typeFilters(char c)
	{
		MapFilters list = filters;
		if (list != null && !Character.isISOControl(c))
		{
			list.type(c);
		}
	}

	private void backspaceFilters()
	{
		MapFilters list = filters;
		if (list != null)
		{
			list.backspace();
		}
	}

	private MapIcons.Shown iconAt(int x, int y, int width, int height)
	{
		MapIcons current = icons;
		if (current == null)
		{
			// the plugin is stopping; the window may still pass on a click
			return null;
		}
		List<MapIcons.Shown> shown = current.visible(viewport().view(width, height), area, plane, settings, progress);
		return MapIcons.at(shown, x, y);
	}

	/**
	 * Moves the map back to the player, on whichever map they are, and keeps it on them as they move ({@link #follow})
	 * until the map is dragged or sent somewhere else.
	 */
	void locate()
	{
		if (player == null)
		{
			return;
		}
		setFollowing(true);
		follow();
	}

	/** While following: the map on the player, on their map and floor. Each frame; also on the locate button. */
	private void follow()
	{
		WorldPoint at = player;
		if (!following || at == null)
		{
			return;
		}
		area = MapArea.of(at.getY());
		plane = at.getPlane();
		viewports.get(area).centerOn(at.getX(), at.getY());
	}

	/** Starts or stops the map following the player; dragging the map or going somewhere stops it. */
	void setFollowing(boolean on)
	{
		following = on;
		MapPainter drawing = painter;
		if (drawing != null)
		{
			drawing.setFollowing(on);
		}
	}

	private void setHidden(MapSpot spot, boolean hide)
	{
		String key = AdvancedMapConfig.HIDDEN_PREFIX + spot.getKey();
		if (hide)
		{
			configManager.setConfiguration(AdvancedMapConfig.GROUP, key, true);
		}
		else
		{
			configManager.unsetConfiguration(AdvancedMapConfig.GROUP, key);
		}
		// the settings are read again, and the Hidden icons list made again, by onConfigChanged for the change
	}

	private void setSwitch(String key, boolean on)
	{
		configManager.setConfiguration(AdvancedMapConfig.GROUP, key, on);
		settings = readSettings();
	}

	/** Which map is shown: the surface or underground. */
	MapArea area()
	{
		return area;
	}

	/** The view of the map that is shown. */
	MapViewport viewport()
	{
		return viewports.get(area);
	}

	/** Switches between the surface and underground maps; each keeps its own place and zoom. */
	void switchArea()
	{
		area = area.other();
	}

	void toggleMap()
	{
		if (windowOpen)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (window != null && window.isMinimized())
				{
					showWindow();
				}
				else
				{
					closeMap();
				}
			});
			return;
		}
		if (mapOpen)
		{
			closeMap();
		}
		else
		{
			openMap(null, null);
		}
	}

	/** Opens the map on a point, or on the player when {@code at} is null; at a zoom, or the last one. */
	void openMap(WorldPoint at, Double zoom)
	{
		// markers another client (another account) added, changed or removed since
		ExecutorService files = markerFiles;
		if (files != null && !isOpen())
		{
			files.execute(this::reloadMarkers);
		}
		clientThread.invokeLater(() ->
		{
			if (!started || reader == null)
			{
				// stopped since the key or the orb asked: what the map needs is gone
				return;
			}
			player = Prifddinas.toSurface(currentPlayerLocation());
			readProgress();
			// and again on the next tick: a map opened in the tick right after a login read the account before its
			// levels and quests had come
			progressDue = true;
			listRegions();
			loadLabels();
			WorldPoint center = at != null ? at : player != null ? player : LUMBRIDGE;
			if (at != null)
			{
				// a place to show (another plugin's, a search's): following the player would move straight off it
				setFollowing(false);
			}
			area = MapArea.of(center.getY());
			plane = center.getPlane();
			MapViewport viewport = viewports.get(area);
			viewport.centerOn(center.getX(), center.getY());
			if (zoom != null)
			{
				viewport.setZoom(zoom);
			}
			boolean wasOpen = mapOpen || windowOpen;
			boolean inWindow = opensInWindow(windowOpen, config.popOut(), inGame());
			showIn(inWindow);
			if (inWindow)
			{
				SwingUtilities.invokeLater(this::showWindow);
			}
			if (!wasOpen)
			{
				postState(true);
				popUp();
			}
		});
	}

	/**
	 * Whether the map opens (or is shown again) in its window rather than over the game: when it is already in its
	 * window (opened on the login screen, say, and asked for again after logging in: never both at once, since the
	 * two paint with one painter and would both take the keys), when the setting says so, and on the login screen,
	 * where RuneLite draws no overlay.
	 */
	static boolean opensInWindow(boolean windowOpen, boolean popOut, boolean loggedIn)
	{
		return windowOpen || popOut || !loggedIn;
	}

	/**
	 * Shows the map in its window or in the box over the game, never both: a box open when the window is asked for
	 * (the pop-out setting turned on meanwhile, then the orb or another plugin's message) closes as the window opens,
	 * as it does for the pop-out button.
	 */
	void showIn(boolean window)
	{
		mapOpen = !window;
		windowOpen = window;
	}

	boolean isWindowOpen()
	{
		return windowOpen;
	}

	/**
	 * Lists the regions the game has, once, so the map knows empty space at once; the preparer lists them too, but only
	 * from ten seconds after launch.
	 */
	private void listRegions()
	{
		RegionImages current = images;
		ClientMapSource from = source;
		if (regionsListing || current == null || current.knowsRegionsInGame())
		{
			return;
		}
		regionsListing = true;
		executor.execute(() ->
		{
			try
			{
				current.setRegionsInGame(from.regionIds());
			}
			catch (RuntimeException e)
			{
				log.debug("could not list the game's regions", e);
			}
			finally
			{
				regionsListing = false;
			}
		});
	}

	/** The game's item pictures on a disc, for the teleports whose icon is an item's: by item id, once loaded. */
	private final Map<Integer, BufferedImage> itemDiscs = new ConcurrentHashMap<>();
	private final Set<Integer> itemDiscsAsked = ConcurrentHashMap.newKeySet();

	/** An item's picture on a disc, or null while the client loads it (asked once; drawn on a later paint). */
	private BufferedImage itemDisc(int itemId)
	{
		BufferedImage disc = itemDiscs.get(itemId);
		if (disc == null && itemDiscsAsked.add(itemId))
		{
			net.runelite.client.util.AsyncBufferedImage item = itemManager.getImage(itemId);
			item.onLoaded(() ->
			{
				// a picture that arrives after the plugin stopped is not kept
				if (started)
				{
					itemDiscs.put(itemId, MapIcons.onDisc(item));
				}
			});
		}
		return disc;
	}

	/** Reads the place names in the background, once; again next time if the client had no world map data yet. */
	/** Whether this run has the map links: until then each opening asks for them again. */
	private volatile boolean linksRead;

	private void loadLabels()
	{
		if (labelsLoading || !labels.all().isEmpty() && filters.hasCategories() && linksRead)
		{
			return;
		}
		labelsLoading = true;
		ClientMapSource from = source;
		MapLabels into = labels;
		MapFilters list = filters;
		MapIcons pictures = icons;
		executor.execute(() ->
		{
			try
			{
				Map<Integer, Integer> categories = from.categoryIcons();
				categories.values().forEach(areaId -> pictures.addSprite(areaId, from.areaIcon(areaId)));
				// the minigame teleports' icon
				pictures.setMinigameArea(categories.getOrDefault(IconGroup.MINIGAME, -1));
				list.setCategoryIcons(categories);
				// all read before any is kept: a part still downloading throws, and the next opening reads it all again
				var names = from.labels();
				var maps = from.gameMaps();
				var pieces = from.mapPieces();
				into.set(names);
				SailingDocks.place(into.all());
				gameMaps = maps;
				MapPainter drawing = painter;
				if (drawing != null)
				{
					drawing.setDungeonMaps(pieces);
				}
				// the links apart: a link script still downloading, or gone after a game update, must not cost the
				// names; they are read again at a later opening
				try
				{
					var links = from.mapLinks();
					if (drawing != null)
					{
						drawing.setMapLinks(links);
					}
					linksRead = true;
				}
				catch (CacheNotReadyException e)
				{
					log.debug("the map links are not there yet");
				}
			}
			catch (RuntimeException e)
			{
				log.debug("could not read the place names", e);
			}
			finally
			{
				labelsLoading = false;
			}
		});
	}

	/** Closes the map, over the game or in its window. */
	void closeMap()
	{
		if (windowOpen)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (window != null)
				{
					window.dispose();
				}
			});
			return;
		}
		if (!mapOpen)
		{
			return;
		}
		mapOpen = false;
		closed();
	}

	/** Moves the map from over the game into its own window, and keeps it there next time (the setting). */
	void popOut()
	{
		configManager.setConfiguration(AdvancedMapConfig.GROUP, "popOut", true);
		// closed over the game first: the overlay and the window paint with one painter, never both at once. A
		// paint of the overlay already under way on the client thread ends before the client thread runs this, and
		// the window's first paint comes after that
		mapOpen = false;
		windowOpen = true;
		clientThread.invokeLater(() -> SwingUtilities.invokeLater(this::showWindow));
	}

	/** Moves the map from its window back over the game, and keeps it there next time. Swing thread. */
	void dock()
	{
		configManager.setConfiguration(AdvancedMapConfig.GROUP, "popOut", false);
		MapWindow open = window;
		window = null;
		windowOpen = false;
		mapOpen = true;
		if (open != null)
		{
			open.dispose();
		}
	}

	/** Swing thread. */
	private void showWindow()
	{
		if (!windowOpen || painter == null)
		{
			return;
		}
		if (window != null && window.isMinimized())
		{
			// the Plugin Hub allows no window manipulation, so a minimized window is not brought back up: it closes
			// and a new one opens in its place, where it was
			MapWindow minimized = window;
			window = null;
			minimized.dispose();
		}
		if (window == null)
		{
			window = new MapWindow(this, painter, this::windowClosed, config.windowBounds(),
				bounds -> configManager.setConfiguration(AdvancedMapConfig.GROUP, AdvancedMapConfig.WINDOW_BOUNDS, bounds));
		}
		window.setVisible(true);
	}

	/** The player closed the window (or the map was closed). Swing thread. */
	private void windowClosed(MapWindow closedWindow)
	{
		if (closedWindow != window)
		{
			// moved back over the game, or replaced
			return;
		}
		window = null;
		windowOpen = false;
		closed();
	}

	private void closed()
	{
		closeMenuLists();
		giveKeysBack();
		// a window closed with the button down never sees the release: hover boxes and tips would stay off
		setDragging(false);
		RegionImages current = images;
		if (current != null)
		{
			current.trim();
		}
		clientThread.invokeLater(() -> postState(false));
	}

	/**
	 * Where the player is in the world. Aboard a boat the player stands in the boat's own small world (its deck, which
	 * the map would show as a few planks in open sea): the spot is moved through the boat to where it sails.
	 */
	private WorldPoint currentPlayerLocation()
	{
		Player local = client.getLocalPlayer();
		LocalPoint at = local == null ? null : local.getLocalLocation();
		if (at == null)
		{
			return null;
		}
		WorldView view = local.getWorldView();
		if (view != null && !view.isTopLevel())
		{
			WorldView top = client.getTopLevelWorldView();
			WorldEntity boat = top == null ? null : top.worldEntities().byIndex(view.getId());
			at = boat == null ? null : boat.transformToMainWorld(at);
			if (at == null)
			{
				return null;
			}
		}
		return WorldPoint.fromLocalInstance(client, at);
	}

	private void postState(boolean open)
	{
		eventBus.post(new PluginMessage(MapMessages.NAMESPACE, "state", Collections.<String, Object>singletonMap("open", open)));
	}
}

