		{
			case PLACE:
			case DUNGEON:
			case MINIGAME:
			case MARKER:
			case ICON:
			case FAIRY_RING:
				return Group.PLACES;
			case MONSTER:
				return Group.MONSTERS;
			case ITEM:
			case GROUND_ITEM:
				return Group.ITEMS;
			default:
				return Group.OTHER;
		}
	}
