public class AreaLoader
{
	public AreaDefinition load(byte[] b, int id)
	{
		InputStream in = new InputStream(b);
		AreaDefinition def = new AreaDefinition();
		def.id = id;

		for (;;)
		{
			int opcode = in.readUnsignedByte();
			if (opcode == 0)
