				break;
			}

			if (!processOpcode(def, in, opcode))
			{
				// an opcode added by a game update: nothing after it can be read in step, so what was read stands
				break;
			}
		}

		return def;
	}

	/** Reads one attribute; false for an opcode this loader does not know. */
