		}
		else if (opcode >= 10 && opcode <= 14)
		{
			def.field3298[opcode - 10] = in.readString();
		}
		else if (opcode == 15)
		{
			int var3 = in.readUnsignedByte();
			def.field3300 = new int[var3 * 2];

			int var4;
			for (var4 = 0; var4 < var3 * 2; ++var4)
