			}

			in.readInt();
			var4 = in.readUnsignedByte();
			def.field3292 = new int[var4];

			int var5;
			for (var5 = 0; var5 < def.field3292.length; ++var5)
			{
				def.field3292[var5] = in.readInt();
			}

			def.field3309 = new byte[var3];

			for (var5 = 0; var5 < var3; ++var5)
