		java.util.function.IntFunction<DungeonPreview.Floor> floors = plane -> plane == 2
			? (x, y) -> x >= 100 && x < 110 && y >= 100 && y < 110 ? DungeonPreview.OPEN : DungeonPreview.CLOSED
			: plane == 0 ? TWO_CAVES : (x, y) -> DungeonPreview.CLOSED;
