		"* Redistributions of source code must retain the above copyright notice, this",
		"  list of conditions and the following disclaimer.",
		"",
		"* Redistributions in binary form must reproduce the above copyright notice,",
		"  this list of conditions and the following disclaimer in the documentation",
		"  and/or other materials provided with the distribution.",
		"",
		"THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS \"AS IS\"",
		"AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE",
		"IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE",
		"DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDER OR CONTRIBUTORS BE LIABLE",
		"FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL",
		"DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR",
		"SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER",
		"CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY,",
		"OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE",
		"OF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.",
	};

	@Test
	public void licenseIsTheHubTemplateWithOnlyTheHolderChanged() throws IOException
	{
		String[] license = new String(Files.readAllBytes(Paths.get("LICENSE")), StandardCharsets.UTF_8)
			.replace("\r\n", "\n").split("\n", -1);
		assertEquals("LICENSE must have the template's lines, and a line break at the end", LICENSE_TEMPLATE.length + 1,
			license.length);
		assertEquals("", license[LICENSE_TEMPLATE.length]);
		for (int i = 0; i < LICENSE_TEMPLATE.length; i++)
		{
			if (i == 2)
			{
				assertTrue("line 3 is the holder's: " + license[i], license[i].matches("Copyright \\(c\\) \\d{4}(-\\d{4})?, .+"));
				continue;
			}
			assertEquals("LICENSE line " + (i + 1) + " differs from RuneLite's", LICENSE_TEMPLATE[i], license[i]);
		}
	}

	@Test
	public void theGuardItselfCatchesEachRule()
	{
		// Prove the scanner fails on a violation, so a green run means something.
		assertEquals(1, violations("import java.lang.reflect.Method;\nclass X {}").size());
		assertEquals(1, violations("class X { void f() throws Exception { Thread.sleep(10); } }").size());
		assertEquals(1, violations("class X { Object g = new Gson(); }").size());
		assertEquals(1, violations("class X { void f() { log.info(\"x\"); } }").size());
		assertEquals(1, violations("class X { void f(Exception e) { e.printStackTrace(); } }").size());
		assertEquals(1, violations("class X { Object f = Filepath.Unchecked.getRooted(null); }").size());
		assertTrue(violations("class X { Object t = new TypeToken<java.util.List<String>>() {}; }").isEmpty());
		// the Toolkit only for its clipboard
		assertTrue(violations("class X { Object c = java.awt.Toolkit.getDefaultToolkit().getSystemClipboard(); }")
			.isEmpty());
		// a listener breaks both rules: the Toolkit's and the input hook's
		assertEquals(2, violations("class X { void f() { Toolkit.getDefaultToolkit().addAWTEventListener(null, 0); } }")
			.size());
		assertEquals(1, violations("class X { Object s = Toolkit.getDefaultToolkit().getScreenSize(); }").size());
		// ...and ignores the same words in comments and strings.
		assertTrue(violations("// Thread.sleep( is forbidden\nclass X { String s = \"new Gson(\"; }").isEmpty());
	}

	/** Every forbidden pattern found in code, with the rule it breaks. */
	static List<String> violations(String source)
	{
		String code = stripCommentsAndStrings(source);
		List<String> found = new ArrayList<>();
		for (String[] rule : FORBIDDEN)
		{
			if (Pattern.compile(rule[0], Pattern.MULTILINE).matcher(code).find())
			{
				found.add(rule[1] + " [" + rule[0] + "]");
			}
		}
		return found;
	}

	private static String stripCommentsAndStrings(String source)
	{
		String noBlockComments = source.replaceAll("(?s)/\\*.*?\\*/", " ");
		String noLineComments = noBlockComments.replaceAll("//[^\\n]*", "");
		return noLineComments.replaceAll("\"(?:\\\\.|[^\"\\\\])*\"", "\"\"");
	}

	private static List<Path> javaFiles(Path root) throws IOException
	{
		List<Path> files = new ArrayList<>();
		if (!Files.exists(root))
		{
			return files;
		}
		try (Stream<Path> walk = Files.walk(root))
		{
			walk.filter(p -> p.toString().endsWith(".java")).forEach(files::add);
		}
		return files;
	}

	private static int readInt(byte[] bytes, int offset)
	{
		return ((bytes[offset] & 0xFF) << 24) | ((bytes[offset + 1] & 0xFF) << 16)
			| ((bytes[offset + 2] & 0xFF) << 8) | (bytes[offset + 3] & 0xFF);
	}
}

