		assertNull(shown.get(1)[1]);
	}

	@Test
	public void theNumberOfLayersIsCapped()
	{
		for (int i = 0; i < MapMessages.MAX_LAYERS + 5; i++)
		{
			messages.handle("layer", map("id", "layer " + i));
		}
		assertEquals(MapMessages.MAX_LAYERS, messages.layers().size());
